@block GroundPlanar begin
    @ports p::Power{Planar}, [frame = "world"]
    @equations begin
        p.f[1] ~ 0.0
        p.f[2] ~ 0.0
        p.f[3] ~ 0.0
    end
    @causality p => (:flow_out, :fixed)
end

@block BodyPlanar begin
    @ports p::Power{Planar}, [frame = "body"]
    @parameters m::Real = 1.0, [unit = "kg", min = 0]
    @parameters J::Real = 0.02, [unit = "kg*m^2", min = 0]
    @variables P::Vec{3} = [0.0, 0.0, 0.0], [state = :prefer]
    @equations begin
        p.f[1] ~ P[1] / J
        p.f[2] ~ P[2] / m
        p.f[3] ~ P[3] / m
        for k in 1:3
            ddt(P[k]) ~ p.e[k]
        end
    end
    @causality p => :flow_out
end
